INSERT INTO opportunities (id, notice_id, solicitation_number, title, type, organization_name, posted_date, active, created_at, updated_at)
SELECT UNHEX(CONCAT(SUBSTR(HEX([[id:02:0]]), 1, 20), LPAD(100 + q.n, 12, '0'))), CONCAT('[[notice:org]]', q.n), NULL, CONCAT('Seed agency notice ', q.n), 'Solicitation', 'SEED 10-15 AGENCY', [[now]] - INTERVAL (q.n + 1) DAY, 0, [[now]], [[now]] FROM (SELECT a.d + 10 * b.d AS n FROM (SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) a CROSS JOIN (SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b) q WHERE q.n BETWEEN 1 AND 21;
INSERT INTO opportunities (id, notice_id, solicitation_number, title, type, organization_name, posted_date, active, awardee_name, award_amount_usd, raw_json, created_at, updated_at)
SELECT UNHEX(CONCAT(SUBSTR(HEX([[id:02:0]]), 1, 20), LPAD(200 + q.n, 12, '0'))), CONCAT('[[notice:aw]]', q.n), CONCAT('SEED-10-15-AWSOL-', q.n), CONCAT('Seed award notice ', q.n), 'Award Notice', 'SEED 10-15 AWARD OFFICE', [[now]] - INTERVAL (2 * q.n + 1) DAY, 0, CONCAT('Seed Notice Awardee ', q.n), 1000 * q.n, JSON_OBJECT('naicsCode', '999170', 'award', JSON_OBJECT('date', DATE_FORMAT(CURDATE() - INTERVAL (2 * q.n + 1) DAY, '%Y-%m-%d'), 'number', CONCAT('SEED-AWD-', q.n))), [[now]], [[now]] FROM (SELECT a.d + 10 * b.d AS n FROM (SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) a CROSS JOIN (SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b) q WHERE q.n BETWEEN 1 AND 25;
INSERT INTO federal_contracts (id, award_key, piid, award_type, recipient_name, start_date, amount_usd, naics_code, description, raw_json, created_at, updated_at)
SELECT UNHEX(CONCAT(SUBSTR(HEX([[id:0d:0]]), 1, 20), LPAD(0 + q.n, 12, '0'))), CONCAT('[[notice:fc]]', q.n), CONCAT('SEED-10-15-PIID-', q.n), 'DEFINITIVE_CONTRACT', CONCAT('Seed Contract Awardee ', q.n), CURDATE() - INTERVAL (2 * q.n) DAY, 1000 * q.n, '999170', CONCAT('Seed contract ', q.n), '{}', [[now]], [[now]] FROM (SELECT a.d + 10 * b.d AS n FROM (SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) a CROSS JOIN (SELECT 0 AS d UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b) q WHERE q.n BETWEEN 1 AND 30;
